// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address newOwner) public {
        // setOwner is restricted to admin (the deployer == this test contract).
        // The candidate owner must differ from the caller (admin), otherwise the
        // buggy overwrite `owner = msg.sender` would coincidentally match.
        vm.assume(newOwner != address(this));

        vm.prank(address(this));
        bool ok;
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }

        assertTrue(ok && c.owner() == newOwner);
    }
}
